-- Ampliación v32: propiedad visual y recibos del evento protegidos.
-- Ejecutar después de 20261031_profile_xp_cosmetics.sql. Reejecutable.
begin;
do $$ begin
 if to_regprocedure('public.hemicycle_put_cloud_save_before_expansion32(jsonb,bigint,uuid)') is null then
  alter function public.hemicycle_put_cloud_save(jsonb,bigint,uuid) rename to hemicycle_put_cloud_save_before_expansion32;
 end if;
end $$;
revoke all on function public.hemicycle_put_cloud_save_before_expansion32(jsonb,bigint,uuid) from public,anon,authenticated,service_role;
create or replace function public.hemicycle_put_cloud_save(p_payload jsonb,p_expected_revision bigint,p_operation_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare saved public.hemicycle_cloud_saves; original jsonb; proposed jsonb; appearance jsonb; choice jsonb; typeface text; item record; response jsonb; first_seen timestamptz; early boolean;
begin
 if auth.uid() is null then raise exception 'Inicia sesión.' using errcode='28000';end if;
 select * into saved from public.hemicycle_cloud_saves where user_id=auth.uid() for update;
 if saved.payload is null then raise exception 'Inicializa el progreso desde el servicio de cuenta.' using errcode='22023';end if;
 if saved.last_operation_id=p_operation_id then return jsonb_build_object('status','saved','save',public.hemicycle_get_cloud_save());end if;
 if saved.revision<>p_expected_revision then return jsonb_build_object('status','conflict','save',public.hemicycle_get_cloud_save());end if;
 original:=saved.payload->'profile';proposed:=p_payload->'profile';appearance:=original->'appearance';
 if appearance is null then
  begin first_seen:=(saved.payload#>>'{identity,createdAt}')::timestamptz;exception when others then first_seen:=saved.updated_at;end;
  first_seen:=least(coalesce(first_seen,saved.updated_at,now()),now());early:=first_seen<'2026-12-01T00:00:00+01:00'::timestamptz;
  appearance:=jsonb_build_object('version',1,'firstSeenAt',to_char(first_seen at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'grandfathered',early,'owned',case when early then '["menu/classic","menu/senate","menu/parchment","menu/book","menu/orbital","menu/hologram","menu/garden","menu/cats","mat/classic","mat/marble","mat/imperial","mat/orbital","mat/garden","mat/cats","mat/hologram","back/classic","back/marble","back/imperial","back/orbital","back/garden","back/cats","back/hologram","coin/classic","coin/marble","coin/imperial","coin/orbital","coin/garden","coin/cats","coin/hologram","font/auto","font/clear","font/classic","font/editorial","font/orbital","font/cats","font/hologram","font/garden"]'::jsonb else '["menu/classic","mat/classic","back/classic","coin/classic","font/auto"]'::jsonb end);
 end if;
 if proposed ? 'appearance' and proposed->'appearance' is distinct from appearance then raise exception 'Los aspectos se conceden al reclamar el logro.' using errcode='22023';end if;
 if proposed ? 'expansionEvent' and proposed->'expansionEvent' is distinct from original->'expansionEvent' then raise exception 'Las entregas del evento se validan en el servidor.' using errcode='22023';end if;
 choice:=proposed->'cosmetics';typeface:=proposed->>'typeface';
 if choice is not null then
  if jsonb_typeof(choice)<>'object' or (select count(*) from jsonb_object_keys(choice))<>4 or not (choice ?& array['menu','mat','back','coin']) then raise exception 'Selección visual no válida.' using errcode='22023';end if;
  for item in select key,value from jsonb_each_text(choice) loop
   if not (appearance->'owned' ? (item.key||'/'||item.value)) then raise exception 'Este aspecto no pertenece a tu colección.' using errcode='22023';end if;
  end loop;
 end if;
 if typeface is not null and not (appearance->'owned' ? ('font/'||typeface)) then raise exception 'Esta tipografía no pertenece a tu colección.' using errcode='22023';end if;
 if proposed->>'battleTheme'='marble' and not (appearance->'owned' ? 'mat/marble') then raise exception 'Este tapete no pertenece a tu colección.' using errcode='22023';end if;
 -- Delegate resource, cabinet, XP and revision checks without giving the older
 -- validator a new cosmetic ID. Its stored protected fields remain identical.
 proposed:=proposed-array['appearance','expansionEvent','typeface','cosmetics'];
 for item in select key,value from jsonb_each(original) where key=any(array['appearance','expansionEvent','typeface','cosmetics']) loop proposed:=proposed||jsonb_build_object(item.key,item.value);end loop;
 -- The XP wrapper validates its submitted choice. Remove it on both sides only
 -- within this locked transaction; the immutable selection is restored below.
 update public.hemicycle_cloud_saves set payload=payload#-'{profile,cosmetics}' where user_id=auth.uid();
 proposed:=proposed-'cosmetics';
 response:=public.hemicycle_put_cloud_save_before_expansion32(jsonb_set(p_payload,'{profile}',proposed),p_expected_revision,p_operation_id);
 if response->>'status'='saved' then
  update public.hemicycle_cloud_saves set payload=jsonb_set(payload,'{profile,appearance}',appearance) where user_id=auth.uid();
  choice:=coalesce(choice,original->'cosmetics');
  if choice is not null then update public.hemicycle_cloud_saves set payload=jsonb_set(payload,'{profile,cosmetics}',choice) where user_id=auth.uid();end if;
  typeface:=coalesce(typeface,original->>'typeface');
  if typeface is not null then update public.hemicycle_cloud_saves set payload=jsonb_set(payload,'{profile,typeface}',to_jsonb(typeface)) where user_id=auth.uid();end if;
  response:=jsonb_build_object('status','saved','save',public.hemicycle_get_cloud_save());
 end if;
 return response;
end $$;
revoke all on function public.hemicycle_put_cloud_save(jsonb,bigint,uuid) from public,anon;
grant execute on function public.hemicycle_put_cloud_save(jsonb,bigint,uuid) to authenticated;

create or replace function public.hemicycle_offline_download(p_actor uuid,p_rules text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare saved public.hemicycle_cloud_saves; n integer; tickets jsonb; context jsonb; total integer;
begin
 if p_rules not in ('offline1','offline2','offline3','offline4','offline5','offline6','offline7','offline8','offline9') then raise exception 'Reglas no compatibles.';end if;
 select * into saved from public.hemicycle_cloud_saves where user_id=p_actor for update;
 if saved.payload is null then raise exception 'Activa primero la nube.';end if;
 context:=jsonb_build_object('leagueDiv',coalesce((saved.payload#>>'{league,div}')::integer,3),'album',(select jsonb_agg(id order by id) from(select distinct value as id from jsonb_array_elements(saved.payload#>'{profile,album}')) x),'actionAlbum',coalesce((select jsonb_agg(id order by id) from(select distinct value as id from jsonb_array_elements(coalesce(saved.payload#>'{profile,actionAlbum}','[]'))) x),'[]'),'elo',saved.payload#>'{profile,elo}','dtGoldActive',saved.payload#>'{profile,dtGoldActive}','dtGoldUnlocked',saved.payload#>'{profile,dtGoldUnlocked}');
 if saved.payload#>'{profile,leaderMastery}' is not null then context:=context||jsonb_build_object('leaderMastery',saved.payload#>'{profile,leaderMastery}');end if;
 select count(*) into n from public.hemicycle_offline_tickets where user_id=p_actor and result is null and expires_at>now() and profile=context and rules=p_rules;
 select count(*) into total from public.hemicycle_offline_tickets where user_id=p_actor and result is null and expires_at>now();
 if n<10 then
  insert into public.hemicycle_offline_tickets(id,user_id,seed,profile,rules)
   select gen_random_uuid(),p_actor,floor(random()*4294967296)::bigint,context,p_rules from generate_series(1,10-n);
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'seed',seed,'profile',profile,'rules',rules,'expires',floor(extract(epoch from expires_at)*1000)) order by issued_at desc,id),'[]') into tickets from public.hemicycle_offline_tickets where user_id=p_actor and result is null and expires_at>now() and profile=context and rules=p_rules;
 return tickets;
end $$;

revoke all on function public.hemicycle_offline_download(uuid,text) from public,anon,authenticated;
grant execute on function public.hemicycle_offline_download(uuid,text) to service_role;
notify pgrst,'reload schema';

